#include <bits/stdc++.h>
using namespace std;const long long P=1e9;long long a[10][10];int u[15],v[15],f[10];int g(int x){return f[x]==x?x:f[x]=g(f[x]);}long long d(int n){if(n==1)return 1;int k=n-1;long long z=1;for(int i=0;i<k;i++)for(int j=i+1;j<k;j++)while(a[j][i]){long long q=a[i][i]/a[j][i];for(int x=i;x<k;x++)a[i][x]=(a[i][x]-q*a[j][x]%P+P)%P;for(int x=i;x<k;x++)swap(a[i][x],a[j][x]);z=P-z;}for(int i=0;i<k;i++)z=z*a[i][i]%P;return z;}int main(int c,char**v0){ios::sync_with_stdio(0);cin.tie(0);int R=c>1?stoi(v0[1]):1000;unsigned long long s=c>2?stoull(v0[2]):1;mt19937_64 h(s);while(R--){int n=h()%6+1,e=0;memset(a,0,sizeof a);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(h()%3==0){u[e]=i;v[e++]=j;a[i][i]++;a[j][j]++;a[i][j]=a[j][i]=P-1;}long long x=0;for(int q=0;q<(1<<e);q++)if(__builtin_popcount(q)==n-1){for(int i=0;i<n;i++)f[i]=i;bool z=1;for(int i=0;i<e;i++)if(q>>i&1){int p=g(u[i]),r=g(v[i]);if(p==r){z=0;break;}f[p]=r;}x+=z;}if(d(n)!=x%P)return cout<<"WA\n",1;}cout<<"OK\n";}
